import{_ as n,C as a,o,c as i,E as r,a2 as s}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"Enterprise Agent Control Planes Need Decision Envelopes, Not Configuration Precedence Alone","description":"","frontmatter":{"title":"Enterprise Agent Control Planes Need Decision Envelopes, Not Configuration Precedence Alone","date":"2026-08-06","column":"industry-architecture","category":"daily","summary":"Managed settings can express organizational intent, but enterprise agent governance must bind policy provenance, principal, capability, model, sandbox, and resumed context to each consequential execution and collect enforcement receipts.","item_id":"Q-20260806-02","source_research_object":"research/analysis/Q-20260806-02-enterprise-agent-control-plane.md","source_reading_result":"research/reading/Q-20260806-02-enterprise-agent-control-plane.md","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep","cover":"/assets/covers/daily-2026-08-06-enterprise-agent-decision-envelope-cover-v2.jpg"},"headers":[],"relativePath":"en/industry/2026-08-06-enterprise-agent-decision-envelope.md","filePath":"en/industry/2026-08-06-enterprise-agent-decision-envelope.md","lastUpdated":1787407830000}'),d={name:"en/industry/2026-08-06-enterprise-agent-decision-envelope.md"};function c(l,e,u,p,h,m){const t=a("ArticleCover");return o(),i("div",null,[r(t,{image:"/assets/covers/daily-2026-08-06-enterprise-agent-decision-envelope-cover-v2.jpg",kicker:"Industry Architecture · Daily Research",title:"Enterprise Agent Control Planes Need Decision Envelopes, Not Configuration Precedence Alone",summary:"Managed settings can express organizational intent, but enterprise agent governance must bind policy provenance, principal, capability, model, sandbox, and resumed context to each consequential execution and collect enforcement receipts.",version:"Q-20260806-02",status:"Daily Runtime V5 · 2026-08-06",languageHref:"/zh/industry/2026-08-06-enterprise-agent-decision-envelope",languageLabel:"中文"}),e[0]||(e[0]=s(' # Enterprise Agent Control Planes Need Decision Envelopes, Not Configuration Precedence Alone <p>Enterprise coding-agent governance is distributed across managed settings, tool permissions, operating-system sandboxing, model selection, and session resume. Configuration can declare whose policy has priority, but it cannot by itself prove that every execution path applied the same policy.</p><h2 id="central-judgment" tabindex="-1">Central judgment <a class="header-anchor" href="#central-judgment" aria-label="Permalink to &quot;Central judgment&quot;">​</a></h2><p><strong>An enterprise agent control plane should issue a versioned decision envelope for each consequential execution and require an enforcement receipt from the execution point.</strong> The envelope should bind policy provenance, principal, requested capability, actual model, sandbox mode, and resumed context.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>This candidate consumes only the Research Object authorized for Production. Its evidence boundary is the completed same-day Reading Result. Production did not reproduce a security bypass and does not upgrade vendor fix notes into independently validated results.</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><p>The Research Object places organization policy distribution, permission prompts, OS sandboxing, model fallback, and session resume inside one architecture problem. It also preserves a contradiction: official documentation gives managed settings the highest precedence, while release notes describe execution paths that had bypassed a managed disable policy or workflow sandbox boundary. Configuration authority and enforcement-path conformance are therefore separate concerns.</p><h2 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control surface</th><th>Intended policy</th><th>Required execution evidence</th><th>What the current evidence does not establish</th></tr></thead><tbody><tr><td>Managed settings</td><td>Organization policy and precedence</td><td>Effective policy version and provenance</td><td>Every path enforced the same policy</td></tr><tr><td>Tool permissions</td><td>Whether a class of tools is allowed</td><td>Request, decision, actor, and reason</td><td>Complete coverage of child processes and bypass paths</td></tr><tr><td>OS sandbox</td><td>System boundary for Bash and child processes</td><td>Actual sandbox mode and failure behavior</td><td>Cross-platform equivalence and universal fail-closed behavior</td></tr><tr><td>Model fallback</td><td>Substitution of execution identity</td><td>Requested model, actual model, reason, and property changes</td><td>Authorization and semantic equivalence of the fallback</td></tr><tr><td>Session resume</td><td>Continuation of prior work</td><td>Working directory, policy, model, sandbox, and outstanding-effect manifest</td><td>Full semantic equivalence to the original context</td></tr></tbody></table><p>Each row distinguishes documented intent, the evidence a runtime should emit, and unknowns. Vendor statements are not treated as independent validation.</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><p>Highest-precedence configuration is necessary, but it is not a complete control plane. Agents, skills, workflows, commands, child processes, and resume paths can become separate enforcement points. The control plane must prove that each point applied the same effective policy or fail closed when it cannot.</p><p>Model fallback should not be reduced to a warning. A changed model can alter cost, residency, capability, and safety properties, so substitution belongs inside the authorization decision. Session resume likewise restores more than conversation text: it restores working directory, policy version, actual model, sandbox state, and unresolved effects.</p><h2 id="engineering-impact" tabindex="-1">Engineering impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering impact&quot;">​</a></h2><p>For enterprise Digital Employees, Position and WorkOrder should resolve into an effective policy snapshot before consequential work begins. Each Operation Node should receive a decision envelope and return a receipt naming the actual execution identity and policy version. Model substitution, sandbox unavailability, and resumed-context drift should enter configured allow, deny, or escalation paths.</p><p>For CodeFlowMu, policy resolution should be a projection separate from FCoP lifecycle state. Requested and actual model, sandbox mode, permission decision, and policy provenance should be durable operation evidence. Resume should compare a stored context manifest with the restored runtime and block or escalate material drift.</p><h2 id="boundaries-and-counter-evidence" tabindex="-1">Boundaries and counter-evidence <a class="header-anchor" href="#boundaries-and-counter-evidence" aria-label="Permalink to &quot;Boundaries and counter-evidence&quot;">​</a></h2><p>The evidence consists of official release notes and documentation, not an independent advisory, exploit reproduction, platform regression matrix, or measured incident reduction. Current documentation may also differ from the implementation state at release time. This candidate presents an architectural judgment, not an independently proven security result.</p><h2 id="future-work" tabindex="-1">Future work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future work&quot;">​</a></h2><p>Further work should determine which decisions must remain centralized, which may be cached with verifiable provenance, which model-property changes require re-authorization, how every execution path proves policy-version conformance, and which resume differences must block continued work.</p><h2 id="visualization-note" tabindex="-1">Visualization note <a class="header-anchor" href="#visualization-note" aria-label="Permalink to &quot;Visualization note&quot;">​</a></h2><p>The visual centers the decision envelope and links policy, principal and capability, model, sandbox, and resumed context to enforcement receipts. It is a Research Center architecture synthesis based on the Research Object.</p><h2 id="evidence-and-references" tabindex="-1">Evidence and references <a class="header-anchor" href="#evidence-and-references" aria-label="Permalink to &quot;Evidence and references&quot;">​</a></h2><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260806-02-enterprise-agent-control-plane.md" target="_blank" rel="noreferrer">Research Object</a>: the sole analytical input, explicitly separating documented policy, enforcement conformance, and independent-validation gaps.</li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260806-02-enterprise-agent-control-plane.md" target="_blank" rel="noreferrer">Reading Result</a>: the evidence boundary and source-traceability record declared by the Research Object; this candidate does not re-research it.</li></ol>',25))])}const f=n(d,[["render",c]]);export{g as __pageData,f as default};
